package sourcemap

import (
	"testing"

	"github.com/alexandrmotologa/errpulse/internal/ingest"
	"github.com/alexandrmotologa/errpulse/internal/storage"
)

func TestSourceMapVLQ(t *testing.T) {
	// Sample source map v3 generated by TypeScript / esbuild
	// Source code:
	// 0: const add = (a: number, b: number) => {
	// 1:   return a + b;
	// 2: };
	// Minified:
	// const add=(a,b)=>a+b;
	sampleMapJSON := `{
		"version": 3,
		"file": "bundle.min.js",
		"sources": ["src/math.ts"],
		"sourcesContent": [
			"export const add = (a: number, b: number): number => {\n  const result = a + b;\n  return result;\n};"
		],
		"names": ["add", "a", "b", "result"],
		"mappings": "AAAA,OAAO,MAAMA,EAAM,CAACC,EAAWC,IAAmB;AAChD,QAAMC,EAASF,EAAIC;AACnB,SAAOC;AACT;"
	}`

	parsed, err := ParseSourceMap([]byte(sampleMapJSON))
	if err != nil {
		t.Fatalf("Failed parsing source map: %v", err)
	}

	if len(parsed.Lines) == 0 {
		t.Fatalf("Expected parsed lines")
	}

	// Lookup line 0, col 10 in generated bundle
	file, origLine, origCol, _, found := parsed.Lookup(0, 10)
	if !found {
		t.Fatalf("Expected mapping lookup to succeed")
	}

	if file != "src/math.ts" {
		t.Errorf("Expected source file 'src/math.ts', got '%s'", file)
	}

	// Verify context line extraction
	pre, line, post := parsed.GetContextLines(0, origLine, 2)
	if line == "" {
		t.Errorf("Expected non-empty context line")
	}
	_ = pre
	_ = post
	_ = origCol
}

func TestResolver(t *testing.T) {
	db, err := storage.Open(":memory:")
	if err != nil {
		t.Fatalf("Failed opening test db: %v", err)
	}
	defer db.Close()

	sampleMapJSON := `{
		"version": 3,
		"file": "bundle.js",
		"sources": ["src/calculator.ts"],
		"sourcesContent": [
			"export function calculate() {\n  throw new Error('Boom');\n}"
		],
		"names": ["calculate"],
		"mappings": "AAAA,eAAe,SAASA;AACtB,QAAM,IAAI,MAAM;"
	}`

	err = db.SaveArtifact(1, "v1.0.0", "bundle.js.map", "application/json", []byte(sampleMapJSON))
	if err != nil {
		t.Fatalf("Failed saving artifact: %v", err)
	}

	resolver := NewResolver(db)
	minifiedFrames := []ingest.SentryFrame{
		{
			Filename: "bundle.js",
			Lineno:   2,
			Colno:    10,
			Function: "t",
		},
	}

	remapped := resolver.RemapStacktrace(1, "v1.0.0", minifiedFrames)
	if len(remapped) != 1 {
		t.Fatalf("Expected 1 remapped frame")
	}

	frame := remapped[0]
	if frame.Filename != "src/calculator.ts" {
		t.Errorf("Expected remapped filename 'src/calculator.ts', got '%s'", frame.Filename)
	}
	if frame.Lineno != 2 {
		t.Errorf("Expected lineno 2, got %d", frame.Lineno)
	}
	if frame.ContextLine != "  throw new Error('Boom');" {
		t.Errorf("Expected context line '  throw new Error('Boom');', got '%s'", frame.ContextLine)
	}
}
